/* ================= новый интерфейс: плавающие острова ================= */
:root{
  --acc:var(--accL, #3d4af0); --acc-soft:color-mix(in srgb, var(--acc) 12%, transparent); --acc-ring:color-mix(in srgb, var(--acc) 38%, transparent); --acc-sel:color-mix(in srgb, var(--acc) 22%, transparent);
