}
@media (prefers-color-scheme: dark){ :root:not([data-theme="light"]){
  --acc:var(--accD, #8d97ff); --acc-soft:color-mix(in srgb, var(--acc) 18%, transparent); --acc-ring:color-mix(in srgb, var(--acc) 42%, transparent); --acc-sel:color-mix(in srgb, var(--acc) 30%, transparent);
  --island:rgba(22,22,24,.74); --island-line:rgba(255,255,255,.09);
  --island-shadow:0 1px 0 rgba(255,255,255,.04) inset, 0 18px 40px -16px rgba(0,0,0,.85);
  --line2:rgba(255,255,255,.16); --tipbg:#f2f2f0; --tipfg:#0a0a0a;
  --desk:#0a0a0a; --ui:#0a0a0a; --uiink:#f2f2f0; --hover:rgba(255,255,255,.08); --press:rgba(255,255,255,.15);
  --sb:rgba(255,255,255,.22); --pageline:rgba(255,255,255,.1);
  --pageshadow:0 30px 80px -30px #000, 0 0 0 1px rgba(255,255,255,.03);
} }
:root[data-theme="dark"]{
  --acc:var(--accD, #8d97ff); --acc-soft:color-mix(in srgb, var(--acc) 18%, transparent); --acc-ring:color-mix(in srgb, var(--acc) 42%, transparent); --acc-sel:color-mix(in srgb, var(--acc) 30%, transparent);
  --island:rgba(22,22,24,.74); --island-line:rgba(255,255,255,.09);
  --island-shadow:0 1px 0 rgba(255,255,255,.04) inset, 0 18px 40px -16px rgba(0,0,0,.85);
  --line2:rgba(255,255,255,.16); --tipbg:#f2f2f0; --tipfg:#0a0a0a;
