:root[data-theme="dark"] .page-bg, :root[data-theme="dark"] .pmask .pgapfill{ border-color:var(--pageline); }
.exporting .page-bg{ box-shadow:none !important; border:0 !important; border-radius:0 !important; }

/* плашка внизу: какой лист и сколько слов */
#status{ position:fixed; left:14px; bottom:calc(14px + env(safe-area-inset-bottom,0px)); z-index:12; display:flex; align-items:center; gap:10px;
  padding:8px 14px; border-radius:999px; background:var(--island); border:1px solid var(--island-line); box-shadow:var(--island-shadow);
  -webkit-backdrop-filter:blur(18px) saturate(1.4); backdrop-filter:blur(18px) saturate(1.4);
  color:var(--uiink); font:500 12.5px/1 var(--head); font-variant-numeric:tabular-nums; pointer-events:none; animation:barIn .6s var(--ease) .2s both; }
