@media print{ #status{ display:none !important; } }

/* ================= выбор цвета темы ================= */
.acc-pop{ position:absolute; right:0; top:54px; width:236px; padding:12px; border-radius:16px; background:var(--island); border:1px solid var(--island-line);
  box-shadow:var(--island-shadow); -webkit-backdrop-filter:blur(22px) saturate(1.4); backdrop-filter:blur(22px) saturate(1.4);
  color:var(--uiink); z-index:25; visibility:hidden; opacity:0; transform:translateY(-6px) scale(.97); transform-origin:100% 0;
  transition:opacity .2s var(--ease), transform .2s var(--ease), visibility 0s linear .2s; }
