.acc-pop .sw:hover{ transform:scale(1.1); }
.acc-pop .sw.on{ box-shadow:0 0 0 2px var(--island), 0 0 0 4px var(--uiink) !important; }
.acc-pop .sw[data-tip]::after{ display:none; }
.acc-pop .custom{ display:block; overflow:hidden; background:conic-gradient(#f43f5e,#f59e0b,#84cc16,#10b981,#06b6d4,#3b82f6,#8b5cf6,#ec4899,#f43f5e) !important; }
.acc-pop .custom input{ position:absolute; inset:-8px; width:calc(100% + 16px); height:calc(100% + 16px); opacity:0; cursor:pointer; border:0; padding:0; }
.bar .acc-pop button.sw.on{ background:var(--cl) !important; color:inherit !important; filter:none; }
