.acc-pop .sws{ grid-template-columns:repeat(6,1fr) !important; gap:7px !important; }
.acc-pop .nm{ font:500 12px/1 var(--head); margin:10px 2px 0; opacity:.7; min-height:12px; }
#bAccent svg .dot{ fill:var(--acc); stroke:none; }

/* Палитра выделения текста в меню цвета темы */
.acc-pop{ width:250px; }
