  --desk:#f2f4f7; --ui:#ffffff; --uiink:#20242b;
  --theme-panel:#ffffff; --theme-text:#20242b; --theme-muted:#737b87;
  --theme-border:#dfe3e8; --theme-hover:#f0f2f5; --theme-shadow:0 10px 30px rgba(20,30,45,.09);
