body{color:var(--theme-text)!important;transition:background-color .2s ease,color .2s ease;}
.bar{background:var(--ui)!important;color:var(--uiink)!important;border-color:var(--theme-border)!important;box-shadow:0 1px 0 var(--theme-border),0 6px 24px rgba(0,0,0,.04)!important;}
.bar button{color:var(--uiink)!important;border-color:transparent!important;border-radius:10px!important;}
.bar button:hover,.bar button.on{background:var(--theme-hover)!important;border-color:var(--theme-border)!important;}
