.picker,.acc-pop,.accPop,.popover,.menu,.dropdown,.dialog,.modal,#accPop{background:var(--theme-panel)!important;color:var(--theme-text)!important;border-color:var(--theme-border)!important;box-shadow:var(--theme-shadow)!important;}
