.acc-pop .mark-custom.on{box-shadow:0 0 0 2px var(--island,#fff),0 0 0 4px var(--uiink,#222)!important}
.acc-pop .mark-sws{display:flex;flex-wrap:nowrap;overflow-x:auto;gap:8px;padding:5px 4px 10px;scrollbar-width:thin;overscroll-behavior-x:contain}



@font-face{font-family:"TT Interphases";src:local("TT Interphases"),local("TTInterphases");font-display:swap}
@font-face{font-family:"TT Interphases Mono";src:local("TT Interphases Mono"),local("TTInterphasesMono");font-display:swap}



:root{--ref-desk:#e9ebf0;--ref-ui:#fff;--ref-ink:#17181d;--ref-line:rgba(22,24,32,.09);--ref-shadow:0 2px 8px rgba(20,22,30,.05),0 18px 42px -22px rgba(20,22,30,.28);}
:root[data-theme="light"]{--desk:#e9ebf0!important;--ui:#fff!important;--uiink:#17181d!important;--ref-desk:#e9ebf0;--ref-ui:#fff;--ref-ink:#17181d;--ref-line:rgba(22,24,32,.09);--ref-shadow:0 2px 8px rgba(20,22,30,.05),0 18px 42px -22px rgba(20,22,30,.28);color-scheme:light;}
:root[data-theme="dark"]{--desk:#0b0b0c!important;--ui:#171719!important;--uiink:#f4f4f5!important;--ref-desk:#0b0b0c;--ref-ui:#171719;--ref-ink:#f4f4f5;--ref-line:rgba(255,255,255,.09);--ref-shadow:0 2px 8px rgba(0,0,0,.2),0 18px 42px -22px rgba(0,0,0,.8);color-scheme:dark;}
body{background:var(--ref-desk)!important;transition:background .2s ease;color:var(--ref-ink);}
.bar{position:sticky!important;top:8px!important;width:max-content;max-width:calc(100% - 24px);margin:8px auto 18px!important;padding:6px 9px!important;border:1px solid var(--ref-line)!important;border-radius:18px!important;background:var(--ref-ui)!important;color:var(--ref-ink)!important;box-shadow:var(--ref-shadow)!important;}
.bar .tools{gap:3px!important;}
.bar button{border-radius:9px!important;transition:background .15s ease,border-color .15s ease,transform .15s ease!important;}
.bar button:hover{background:var(--hover,rgba(100,100,100,.1))!important;}
.bar .right{position:fixed!important;top:8px!important;right:10px!important;z-index:20!important;display:flex;align-items:center;gap:5px;padding:5px 6px;border:1px solid var(--ref-line);border-radius:16px;background:var(--ref-ui);box-shadow:var(--ref-shadow);}
#bTheme{display:grid;place-items:center;border:1px solid transparent!important;border-radius:9px!important;background:transparent!important;color:var(--ref-ink)!important;cursor:pointer;}
#bTheme:hover{background:var(--hover,rgba(100,100,100,.1))!important;border-color:var(--ref-line)!important;}
#bTheme:focus-visible{outline:2px solid var(--ref-ink);outline-offset:1px}
#bTheme svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;shape-rendering:geometricPrecision;}
.page-bg{background:#fff!important;border-color:rgba(0,0,0,.08)!important;box-shadow:var(--ref-shadow)!important;}
:root[data-theme="dark"] .page-bg{background:#fff!important;}
:root[data-theme="dark"] .docbody{color:#111!important;}
.acc-pop{border:1px solid var(--ref-line)!important;border-radius:14px!important;box-shadow:var(--ref-shadow)!important;}
#fontChoice{border-radius:14px!important;box-shadow:var(--ref-shadow)!important;}
.font-option{border-radius:10px!important;transition:background .15s,border-color .15s!important;}
@media(max-width:900px){.bar{margin-right:auto!important;margin-left:8px!important;max-width:calc(100% - 100px)!important;}.bar .right{right:8px!important;}}
@media(prefers-reduced-motion:reduce){body,.bar button{transition:none!important}}



/* ── 1. Панель выбора шрифтов (Aa) ── */
.font-tool-wrap{position:relative;display:inline-flex;align-items:center}
.font-pop{
  position:absolute;z-index:150;top:calc(100% + 10px);left:0;
  width:320px;max-width:calc(100vw - 24px);padding:16px;
  background:var(--theme-panel,#fff);color:var(--theme-text,#1e2229);
  border:1px solid var(--theme-border,#dde1e8);border-radius:18px;
  box-shadow:0 22px 60px rgba(0,0,0,.18), 0 4px 16px rgba(0,0,0,.06);
  display:flex;flex-direction:column;gap:12px;
  animation:fontPopAnim .18s cubic-bezier(.16,1,.3,1);
}
.font-pop[hidden]{display:none!important}
@keyframes fontPopAnim{from{opacity:0;transform:translateY(-6px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}

.font-pop-head{display:flex;align-items:center;gap:10px;padding-bottom:12px;border-bottom:1px solid var(--theme-border,#e5e8ee)}
.font-pop-icon{
  display:grid;place-items:center;width:38px;height:38px;border-radius:11px;
  background:var(--theme-hover,#f1f4f8);font-size:17px;font-weight:800;letter-spacing:-1px;
  box-shadow:inset 0 0 0 1px var(--theme-border,#e5e8ee);flex-shrink:0
}
.font-pop-head strong{display:block;font-size:13.5px;font-weight:700;line-height:1.25}
.font-pop-head small{display:block;color:var(--theme-muted,#788190);font-size:11px;margin-top:2px}

.font-card-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.font-card{
  display:flex;flex-direction:column;gap:4px;padding:10px 11px;
  border:1.5px solid var(--theme-border,#dfe3ea);border-radius:12px;
  background:var(--theme-panel,#fff);color:var(--theme-text,#1e2229);
  cursor:pointer;transition:border-color .15s,background .15s,transform .12s,box-shadow .15s;text-align:left;
}
.font-card:hover{background:var(--theme-hover,#f4f6fa);border-color:var(--acc,#4f7cff);transform:translateY(-1px)}
.font-card.active{
  border-color:var(--acc,#4f7cff);
  background:color-mix(in srgb,var(--acc,#4f7cff) 10%,var(--theme-panel,#fff));
  box-shadow:0 0 0 3px color-mix(in srgb,var(--acc,#4f7cff) 18%,transparent);
}
.font-card .fc-sample{font-size:20px;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.font-card .fc-name{font:600 10px/1.3 Inter,system-ui,sans-serif;color:var(--theme-text,#1e2229);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.font-card .fc-desc{font:400 9.5px/1.2 Inter,system-ui,sans-serif;color:var(--theme-muted,#788190);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

.font-pop-preview{
  border:1px solid var(--theme-border,#e2e5ea);background:var(--theme-hover,#f6f8fa);
  border-radius:11px;padding:10px 12px;display:flex;flex-direction:column;gap:4px;overflow:hidden
}
.font-pop-preview .fp-big{font-size:18px;line-height:1.25;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.font-pop-preview .fp-small{font:400 10.5px/1.3 Inter,system-ui,sans-serif;color:var(--theme-muted,#788190);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.font-pop .font-note{font:400 10.5px/1.4 Inter,system-ui,sans-serif;color:var(--theme-muted,#788190);margin:0}

:root[data-theme="dark"] .font-pop{background:#181b22;border-color:#303642;color:#f0f3f6;box-shadow:0 22px 60px rgba(0,0,0,.6)}
:root[data-theme="dark"] .font-pop-head{border-bottom-color:#303642}
:root[data-theme="dark"] .font-pop-icon{background:#222630;box-shadow:inset 0 0 0 1px #303642}
:root[data-theme="dark"] .font-card{background:#1e222a;border-color:#323846;color:#f0f3f6}
:root[data-theme="dark"] .font-card:hover{background:#262b37;border-color:#8692ff}
:root[data-theme="dark"] .font-card.active{background:#282f42;border-color:#8692ff}
:root[data-theme="dark"] .font-card .fc-name{color:#f0f3f6}
:root[data-theme="dark"] .font-pop-preview{background:#1e222a;border-color:#323846}

/* ── 2. Двухколоночная палитра (Цвета темы | Цвет выделения текста) ── */
.acc-pop{
  position:absolute;right:0;top:54px;width:auto!important;min-width:390px;max-width:calc(100vw - 24px);
  padding:16px!important;border-radius:18px!important;
  background:var(--theme-panel,#fff)!important;color:var(--theme-text,#1e2229)!important;
  border:1px solid var(--theme-border,#dde1e8)!important;
  box-shadow:0 22px 60px rgba(0,0,0,.18), 0 4px 16px rgba(0,0,0,.06)!important;
  z-index:30;visibility:hidden;opacity:0;transform:translateY(-6px) scale(.98);transform-origin:100% 0;
  transition:opacity .18s ease, transform .18s ease, visibility 0s linear .18s;
}
.acc-pop.open{visibility:visible!important;opacity:1!important;transform:none!important;transition-delay:0s!important}
.acc-cols{display:flex;gap:16px;align-items:stretch;}
.acc-col{flex:1;min-width:160px;display:flex;flex-direction:column;gap:8px;}
.acc-col-head{display:flex;align-items:center;gap:6px;margin-bottom:2px;}
.acc-col-icon{display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;flex:0 0 16px;color:var(--uiink,#1e2229);opacity:.72}
.acc-col-icon svg{width:16px;height:16px;display:block;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;shape-rendering:geometricPrecision;}
.acc-col-icon svg .f{fill:currentColor;stroke:none;}
.acc-col-head .mark-title .acc-col-icon{color:var(--acc,#1e2229);opacity:.9}
.acc-pop .ttl{font:700 12px/1.3 Inter,system-ui,sans-serif!important;color:var(--theme-text,#1e2229);margin:0!important;letter-spacing:-.01em;}
.acc-sep{width:1px;background:var(--theme-border,#e5e8ee);margin:2px 0;align-self:stretch;}
.acc-pop .sws{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;}
.acc-pop .sw{
  width:100%;aspect-ratio:1;height:auto;padding:0;border-radius:10px;border:2px solid transparent;
  cursor:pointer;transition:transform .12s,box-shadow .15s;background:var(--swatch);
}
.acc-pop .sw:hover{transform:scale(1.08)}
.acc-pop .sw.on{border-color:var(--theme-panel,#fff);box-shadow:0 0 0 2.5px var(--uiink,#1e2229)!important}
.acc-pop .mark-swatch{
  width:100%;aspect-ratio:1;height:auto;padding:0;border-radius:10px;border:2px solid transparent;
  cursor:pointer;transition:transform .12s,box-shadow .15s;background:var(--swatch);
}
.acc-pop .mark-swatch:hover{transform:scale(1.08)}
.acc-pop .mark-swatch.on{border-color:var(--theme-panel,#fff);box-shadow:0 0 0 2.5px var(--acc,#4f7cff)!important}
.acc-pop .mark-custom{
  position:relative;overflow:hidden;
  background:conic-gradient(red,yellow,lime,aqua,blue,magenta,red)!important;
}
.acc-pop .mark-custom input[type=color]{position:absolute;inset:-8px;width:150%;height:150%;opacity:0;cursor:pointer}
.acc-pop .nm{font:500 11px/1.3 Inter,system-ui,sans-serif;color:var(--theme-muted,#788190);margin-top:2px;min-height:15px}

:root[data-theme="dark"] .acc-pop{background:#181b22!important;border-color:#303642!important;color:#f0f3f6!important;box-shadow:0 22px 60px rgba(0,0,0,.6)!important}
:root[data-theme="dark"] .acc-sep{background:#303642}
:root[data-theme="dark"] .acc-pop .ttl{color:#f0f3f6}

/* ── 3. Скругление углов картинок как в Canva ── */
.img-cr-wrap{
  display:inline-flex;align-items:center;gap:6px;
  padding:0 8px 0 10px;margin-left:4px;border-left:1px solid rgba(255,255,255,.25);
  font:500 11.5px/1 Inter,system-ui,sans-serif;color:#fff;
}
.img-cr-icon{display:inline-flex;align-items:center;opacity:.85}
.img-cr-wrap input[type=range]{
  width:64px;height:4px;accent-color:var(--acc,#4f7cff);background:rgba(255,255,255,.3);
  border-radius:2px;cursor:pointer;outline:none;
}
.img-cr-val{font:600 11px/1 monospace;min-width:28px;text-align:right;color:#fff}
.img-cr-chips{display:inline-flex;align-items:center;gap:3px;margin-left:4px}
.img-cr-chips button{
  background:rgba(255,255,255,.15)!important;color:#fff!important;border:0!important;
  border-radius:6px!important;padding:2px 5px!important;font:600 10px/1 Inter,system-ui,sans-serif!important;
  cursor:pointer!important;height:20px!important;min-width:20px!important;
}
.img-cr-chips button:hover{background:rgba(255,255,255,.3)!important}
.img-cr-chips button.active{background:var(--acc,#4f7cff)!important;color:#fff!important}
.img-cr-chips button svg{width:13px;height:13px;display:block;fill:none;stroke:currentColor;stroke-width:1.9;shape-rendering:geometricPrecision}



/* ── Refinements for font cards & 2-column palette swatches ── */
