  display:flex!important;flex-direction:column!important;align-items:flex-start!important;justify-content:center!important;
  padding:8px 10px!important;border:1.5px solid var(--theme-border,#dde1e8)!important;border-radius:12px!important;
  background:var(--theme-panel,#fff)!important;color:var(--theme-text,#1e2229)!important;
  box-shadow:0 1px 3px rgba(0,0,0,.04)!important;cursor:pointer!important;text-align:left!important;
}
.bar .font-card:hover{
