  box-shadow:0 0 0 2.5px color-mix(in srgb,var(--acc,#4f7cff) 20%,transparent)!important;
}
:root[data-theme="dark"] .bar .font-card{background:#1e222a!important;border-color:#323846!important;color:#f0f3f6!important}
