  border-radius:9px!important;padding:0!important;border:2px solid transparent!important;
}
.acc-pop .sws{
  display:grid!important;grid-template-columns:repeat(5,1fr)!important;gap:7px!important;
}
.acc-pop .sw{
  width:100%!important;aspect-ratio:1!important;height:auto!important;border-radius:9px!important;
}

/* ── Стили для загрузки своих шрифтов ── */
.font-upload-bar{display:flex;margin-top:2px;width:100%}
.btn-font-upload{
  width:100%!important;height:auto!important;display:inline-flex!important;
  align-items:center!important;justify-content:center!important;gap:7px!important;
