/* ═══════════ Style panel: вкладки Тема / Выделение / Цитата / Таблица / Текст ═══════════ */
:root{ --quote-strip:#e8590c; --quote-bg-opacity:10%; --table-strip-opacity:100%; --table-bg-opacity:0%; --doc-text-opacity:100%; }
.style-panel{ min-width:min(92vw,330px); max-width:min(94vw,380px); }
.sp-tabs{ display:flex; gap:4px; flex-wrap:wrap; margin-bottom:12px; padding-bottom:10px; border-bottom:1px solid var(--ref-line,#e5e8ee); }
.sp-tab{
  flex:1; min-width:54px; padding:7px 6px; border:1px solid var(--ref-line,#e5e8ee);
  border-radius:10px; background:transparent; color:var(--ref-ink,#1e2229);
  font:600 11px/1.2 Inter,system-ui,sans-serif; cursor:pointer;
  transition:background .15s,border-color .15s,color .15s;
}
.sp-tab:hover{ background:var(--hover,rgba(0,0,0,.06)); }
.sp-tab.on{ background:var(--acc-soft); color:var(--acc); border-color:transparent; box-shadow:inset 0 0 0 1px var(--acc-ring); }
.sp-tab:focus-visible{ outline:2px solid var(--acc,#3d4af0); outline-offset:1px; }
.sp-body{ min-height:150px; }
.sp-pane{ display:none; }
.sp-pane.on{ display:block; animation:spFade .15s ease; }
@keyframes spFade{ from{opacity:0; transform:translateY(4px)} to{opacity:1; transform:none} }
.sp-section-title{ font:700 12px/1.3 Inter,system-ui,sans-serif; margin:0 0 8px; color:var(--ref-ink,#1e2229); }
.sp-slider-block{ margin-top:12px; }
.sp-slider-head{
  display:flex; justify-content:space-between; align-items:center;
  font-size:11px; opacity:.75; margin-bottom:6px; gap:8px;
}
.sp-slider-block input[type=range]{
  width:100%; height:5px; accent-color:var(--acc,#3d4af0); cursor:pointer;
}
.sp-divider{ height:1px; background:var(--ref-line,#e5e8ee); margin:14px 0; }
.acc-op-val{ font-size:11px; min-width:32px; text-align:right; opacity:.8; font-variant-numeric:tabular-nums; }
.acc-hint{ font-size:10px; opacity:.55; margin:8px 0 0; line-height:1.35; }
.acc-pop .nm{ margin-top:8px; font-size:11px; opacity:.75; }
:root[data-theme="dark"] .sp-tab{ border-color:rgba(255,255,255,.14); color:#f0f3f6; }
:root[data-theme="dark"] .sp-tab.on{ color:var(--acc,#8d97ff); }

/* ═══════════ Цитата: блок с цветной полосой ═══════════ */
blockquote.quote, .quote{
  --qs: var(--quote-strip, #e8590c);
  --qbg: var(--quote-bg-opacity, 10%);
  margin:12px 0 16px; padding:10px 14px 10px 16px;
  border-left:4px solid var(--qs);
  background:color-mix(in srgb, var(--qs) var(--qbg), transparent);
  border-radius:0 8px 8px 0;
  font-style:italic;
}
blockquote.quote > p, .quote > p{ margin:0 0 6px; }
blockquote.quote > p:last-child, .quote > p:last-child{ margin-bottom:0; }

/* ═══════════ Таблица: полоска шапки и фон ═══════════ */
.tw{
  --tbg: var(--table-bg, var(--acc,#3d4af0));
  --tbg-a: var(--table-bg-opacity, 0%);
  --tstrip: var(--table-strip, var(--acc,#3d4af0));
  --tstrip-a: var(--table-strip-opacity, 100%);
  background: color-mix(in srgb, var(--tbg) var(--tbg-a), transparent);
  border-radius:0 6px 6px 0;
}
.tw.pattern{ border-left:4px solid color-mix(in srgb, var(--tstrip) var(--tstrip-a), transparent); }
.tw.pattern table tr:first-child td{
  background: color-mix(in srgb, var(--tstrip) calc(var(--tstrip-a) * 0.18), transparent);
  border-bottom:2px solid color-mix(in srgb, var(--tstrip) var(--tstrip-a), transparent);
  font-weight:600;
}
.tw.pattern table thead td{
  background: color-mix(in srgb, var(--tstrip) calc(var(--tstrip-a) * 0.18), transparent);
  border-bottom:2px solid color-mix(in srgb, var(--tstrip) var(--tstrip-a), transparent);
  font-weight:600;
}

/* ═══════════ Прозрачность текста документа ═══════════ */
/* Значение переменной хранится как процент ('55%') — подстановка var() внутрь
   calc() в процентах color-mix() не поддерживается частью движков.
   :not(.fill) — чтобы не ломать белый текст на чёрной заливке.
   :not(:where(...)*) — чтобы прозрачность не применялась дважды к вложенным
   (иначе внутри цитаты/ячейки получалось бы 0.55 × 0.55). */
.docbody :where(p,li,td,th,h1,h2,h3,blockquote):not(.fill):not(:where(p,li,td,th,h1,h2,h3,blockquote) *){
  color: color-mix(in srgb, currentColor var(--doc-text-opacity, 100%), transparent);
}



/* ===== Панель действий над выделением (текст / блок / таблица / картинка) ===== */
#selBar{ position:fixed; z-index:40; display:none; align-items:center; gap:2px; padding:4px; background:#14161c; color:#fff;
  border:1px solid rgba(255,255,255,.1); border-radius:12px; box-shadow:0 12px 28px -10px rgba(0,0,0,.55);
  font:500 12px/1 var(--head), Inter, system-ui, sans-serif; -webkit-user-select:none; user-select:none; white-space:nowrap; }
#selBar.on{ display:flex; animation:selPop .16s ease; }
@keyframes selPop{ from{ opacity:0; transform:translateY(4px) scale(.97); } to{ opacity:1; transform:none; } }
#selBar button, #imgUI .sz button.sb-extra{ width:30px; height:30px; min-width:30px; padding:0; border:0; border-radius:8px; background:transparent; color:#fff;
  display:grid; place-items:center; cursor:pointer; font:600 14px/1 var(--head), Inter, system-ui, sans-serif; }
#selBar button:hover{ background:rgba(255,255,255,.16); }
#selBar button.danger:hover{ background:#e03131; }
#selBar button:focus-visible{ outline:2px solid #fff; outline-offset:-2px; }
#selBar svg, #imgUI .sz button.sb-extra svg{ width:18px; height:18px; fill:none; stroke:currentColor; stroke-width:1.8; stroke-linecap:round; stroke-linejoin:round; }
#selBar .lbl{ padding:0 9px 0 7px; opacity:.78; border-right:1px solid rgba(255,255,255,.2); margin-right:2px; }
#selBar .sp{ width:1px; height:18px; background:rgba(255,255,255,.2); margin:0 3px; }
#selBar .aa{ letter-spacing:-.5px; }
#selBar .aa sup{ font-size:10px; margin-left:1px; vertical-align:top; position:relative; top:-1px; }
#imgUI .sz button.sb-extra{ width:auto; min-width:0; height:30px; padding:0 9px; border-radius:0; display:inline-grid; }

#objSel{ position:fixed; z-index:35; display:none; pointer-events:none; border:2px solid var(--acc,#2563eb); border-radius:3px;
  box-shadow:0 0 0 1px rgba(255,255,255,.55); }
#objSel.on{ display:block; }
#objSel i{ position:absolute; width:9px; height:9px; background:#fff; border:2px solid var(--acc,#2563eb); border-radius:50%; }
#objSel i:nth-child(1){ left:-6px; top:-6px; } #objSel i:nth-child(2){ right:-6px; top:-6px; }
#objSel i:nth-child(3){ left:-6px; bottom:-6px; } #objSel i:nth-child(4){ right:-6px; bottom:-6px; }

#objGrip{ position:fixed; z-index:34; display:none; width:24px; height:24px; border-radius:8px; background:var(--acc,#2563eb); color:#fff;
  place-items:center; cursor:pointer; box-shadow:0 6px 14px -6px rgba(0,0,0,.5); }
#objGrip.on{ display:grid; }
#objGrip svg{ width:15px; height:15px; fill:none; stroke:currentColor; stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }
#objGrip:hover{ filter:brightness(1.12); }

/* ===== ИИ-помощник ===== */
#aiFab{ position:fixed; right:18px; top:50%; transform:translateY(-50%); z-index:45; width:48px; height:48px; padding:0; border-radius:16px;
  border:1px solid var(--ref-line, rgba(22,24,32,.1)); background:var(--ref-ui, #fff); color:var(--acc,#2563eb); display:grid; place-items:center; cursor:pointer;
  box-shadow:var(--ref-shadow, 0 10px 30px rgba(20,30,45,.18)); transition:transform .15s ease, background .15s ease, color .15s ease; }
#aiFab:hover{ transform:translateY(-50%) scale(1.07); }
#aiFab.on{ background:var(--acc,#2563eb); color:#fff; }
#aiFab svg{ width:27px; height:27px; fill:none; stroke:currentColor; stroke-width:1.7; stroke-linecap:round; stroke-linejoin:round; }
#aiFab svg .f{ fill:currentColor; stroke:none; }
#aiFab:focus-visible{ outline:2px solid var(--acc,#2563eb); outline-offset:2px; }

#aiPanel{ position:fixed; right:78px; top:50%; transform:translateY(-50%); z-index:46; width:332px; max-height:min(580px, calc(100vh - 90px)); display:none; flex-direction:column;
  background:var(--theme-panel,#fff); color:var(--theme-text,#20242b); border:1px solid var(--theme-border,#dfe3e8); border-radius:18px;
  box-shadow:0 24px 60px -18px rgba(15,23,42,.38); overflow:hidden; font:400 14px/1.4 var(--head), Inter, system-ui, sans-serif; }
#aiPanel.on{ display:flex; animation:aiIn .2s ease; }
@keyframes aiIn{ from{ opacity:0; transform:translateY(-50%) translateX(10px); } to{ opacity:1; transform:translateY(-50%); } }
#aiPanel .ai-head{ display:flex; align-items:center; gap:10px; padding:13px 14px; border-bottom:1px solid var(--theme-border,#dfe3e8); }
#aiPanel .ai-ava{ width:34px; height:34px; border-radius:11px; background:var(--acc-soft, rgba(37,99,235,.12)); color:var(--acc,#2563eb); display:grid; place-items:center; flex:none; }
#aiPanel .ai-ava svg{ width:21px; height:21px; fill:none; stroke:currentColor; stroke-width:1.8; stroke-linecap:round; stroke-linejoin:round; }
#aiPanel .ai-ava svg .f{ fill:currentColor; stroke:none; }
#aiPanel .ai-head b{ display:block; font-weight:650; font-size:14.5px; }
#aiPanel .ai-head small{ color:var(--theme-muted,#737b87); font-size:12px; }
#aiPanel .ai-x{ margin-left:auto; width:28px; height:28px; border:0; border-radius:8px; background:transparent; color:var(--theme-muted,#737b87); font-size:20px; line-height:1; cursor:pointer; }
#aiPanel .ai-x:hover{ background:var(--theme-hover,#f0f2f5); }
#aiBody{ padding:14px; overflow:auto; display:flex; flex-direction:column; gap:12px; }
#aiBody p{ margin:0; }
#aiBody .muted{ color:var(--theme-muted,#737b87); font-size:12.5px; }
#aiBody .ai-btn{ border:0; border-radius:11px; padding:10px 14px; background:var(--acc,#2563eb); color:#fff; font-weight:600; font-size:14px; line-height:1.2; font-family:inherit; cursor:pointer; text-align:center; }
#aiBody .ai-btn:hover{ filter:brightness(1.1); }
#aiBody .ai-btn.ghost{ background:var(--theme-hover,#f0f2f5); color:var(--theme-text,#20242b); }
#aiBody .ai-btn.ghost:hover{ filter:brightness(.96); }
#aiBody .ai-row{ display:flex; gap:8px; flex-wrap:wrap; }
#aiBody .ai-row .ai-btn{ flex:1 1 auto; }
#aiBody .ai-spin{ display:flex; align-items:center; gap:10px; }
#aiBody .ai-spin i{ width:18px; height:18px; border-radius:50%; border:2.5px solid var(--theme-border,#dfe3e8); border-top-color:var(--acc,#2563eb); animation:aiSpin .8s linear infinite; flex:none; }
@keyframes aiSpin{ to{ transform:rotate(360deg); } }
#aiBody .ai-chips{ display:flex; flex-wrap:wrap; gap:7px; }
#aiBody .ai-chip{ min-width:40px; height:40px; padding:0 10px; border-radius:11px; border:1px solid var(--theme-border,#dfe3e8); background:transparent; color:inherit;
  font-weight:600; font-size:14px; line-height:1; font-family:inherit; cursor:pointer; }
#aiBody .ai-chip:hover:not(:disabled){ border-color:var(--acc,#2563eb); color:var(--acc,#2563eb); background:var(--acc-soft, rgba(37,99,235,.1)); }
#aiBody .ai-chip:disabled{ opacity:.35; cursor:default; }
#aiBody .ai-chip.wide{ padding:0 14px; }
#aiBody .ai-done{ display:flex; align-items:center; gap:8px; font-weight:600; }
#aiBody .ai-done svg{ width:20px; height:20px; fill:none; stroke:#1f9d55; stroke-width:2.4; stroke-linecap:round; stroke-linejoin:round; flex:none; }
#aiBody .ai-list{ display:flex; flex-direction:column; gap:6px; max-height:230px; overflow:auto; margin:0 -4px; padding:0 4px; }
#aiBody .ai-fix{ text-align:left; border:1px solid var(--theme-border,#dfe3e8); border-radius:10px; padding:7px 10px; background:transparent; color:inherit; font-family:inherit; font-size:13px; cursor:pointer; }
#aiBody .ai-fix:hover{ border-color:var(--acc,#2563eb); }
#aiBody .ai-fix s{ color:#d6336c; text-decoration-thickness:1.5px; }
#aiBody .ai-fix ins{ color:#1f9d55; text-decoration:none; font-weight:600; }
#aiBody .ai-fix .ctx{ color:var(--theme-muted,#737b87); }
#aiBody .ai-fix ins{ margin-left:1px; }
#aiBody .ai-fix span.why{ display:block; color:var(--theme-muted,#737b87); font-size:11.5px; margin-top:2px; }
#aiBody .ai-item{ display:flex; flex-direction:column; gap:3px; }
#aiBody .ai-links{ display:flex; gap:12px; padding:0 4px 2px; font-size:11.5px; }
#aiBody .ai-links a{ color:var(--acc,#2563eb); text-decoration:none; font-weight:600; }
#aiBody .ai-links a:hover{ text-decoration:underline; }
#aiBody .ai-note{ font-size:12px; color:var(--theme-muted,#737b87); background:var(--theme-hover,#f0f2f5); padding:7px 10px; border-radius:9px; }
::highlight(ai-fix){ background:rgba(46,160,67,.3); }
/* ===== ИИ-помощник: поиск и замена ===== */
#aiBody .fd-grp{ display:flex; flex-direction:column; gap:6px; }
#aiBody .fd-row{ display:flex; gap:6px; align-items:center; }
#aiBody .fd-field{ display:flex; align-items:center; gap:8px; flex:1 1 auto; min-width:0; height:40px; padding:0 11px; box-sizing:border-box;
  border:1px solid var(--theme-border,#dfe3e8); border-radius:11px; background:transparent; color:var(--theme-muted,#737b87); cursor:text;
  transition:border-color .14s ease, box-shadow .14s ease, color .14s ease; }
#aiBody .fd-field:focus-within{ border-color:var(--acc,#2563eb); color:var(--acc,#2563eb); box-shadow:0 0 0 3px var(--acc-soft, rgba(37,99,235,.12)); }
#aiBody .fd-field svg{ width:18px; height:18px; fill:none; stroke:currentColor; stroke-width:1.8; stroke-linecap:round; stroke-linejoin:round; flex:none; }
#aiBody .fd-field input{ flex:1 1 auto; min-width:0; width:100%; border:0; outline:0; padding:0; margin:0; background:transparent; color:var(--theme-text,#20242b);
  font:inherit; font-size:14px; }
#aiBody .fd-field input:focus, #aiBody .fd-field input:focus-visible{ outline:0 !important; box-shadow:none; }   /* фокус рисует рамка-обёртка */
#aiBody .fd-field input::placeholder{ color:var(--theme-muted,#737b87); opacity:1; }
#aiBody .fd-ic{ flex:none; width:36px; height:40px; padding:0; border-radius:10px; border:1px solid var(--theme-border,#dfe3e8); background:transparent; color:var(--theme-text,#20242b);
  display:grid; place-items:center; cursor:pointer; }
#aiBody .fd-ic:hover:not(:disabled){ background:var(--theme-hover,#f0f2f5); border-color:var(--acc,#2563eb); color:var(--acc,#2563eb); }
#aiBody .fd-ic:disabled{ opacity:.35; cursor:default; }
#aiBody .fd-ic svg{ width:18px; height:18px; fill:none; stroke:currentColor; stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }
#aiBody .fd-meta{ display:flex; align-items:center; gap:6px; min-height:28px; font-size:12.5px; color:var(--theme-muted,#737b87); }
#aiBody .fd-count{ font-weight:600; font-variant-numeric:tabular-nums; }
#aiBody .fd-count.none{ color:#d6336c; }
#aiBody .fd-spacer{ flex:1 1 auto; }
#aiBody .fd-tg{ height:28px; padding:0 9px; border-radius:8px; border:1px solid var(--theme-border,#dfe3e8); background:transparent; color:inherit; font-family:inherit;
  font-size:12.5px; font-weight:600; line-height:1; cursor:pointer; }
#aiBody .fd-tg:hover{ border-color:var(--acc,#2563eb); }
#aiBody .fd-tg[aria-pressed="true"]{ background:var(--acc-soft, rgba(37,99,235,.12)); border-color:var(--acc,#2563eb); color:var(--acc,#2563eb); }
#aiBody .ai-btn:disabled{ opacity:.4; cursor:default; filter:none; }
#aiBody .fd-field:focus-within svg{ stroke:currentColor; }

::highlight(ai-find){ background:rgba(255,213,0,.55); color:inherit; }
::highlight(ai-find-cur){ background:rgba(255,128,0,.85); color:#000; }

@media (max-width:720px){
  #aiFab{ right:10px; top:auto; bottom:90px; transform:none; } #aiFab:hover{ transform:scale(1.06); }
  #aiPanel{ left:10px; right:10px; width:auto; top:auto; bottom:150px; transform:none; max-height:60vh; }
  @keyframes aiIn{ from{ opacity:0; transform:translateY(10px); } to{ opacity:1; transform:none; } }
}




/* Native text selection: decoration must not intercept the mouse or enter the clipboard. */
.docbody p, .docbody h1, .docbody h2, .docbody h3,
.docbody ul, .docbody ol { display:block; }
#doc, #hdr, #ftr, .fntext { -webkit-user-select:text; user-select:text; }
#sheets, .page-bg, .pmask, .pgapfill, .bcut, #fnMeasure {
  pointer-events:none; -webkit-user-select:none; user-select:none;
}
.pgap, .pbreak { -webkit-user-select:none; user-select:none; }
#doc::selection, #doc ::selection, #hdr::selection, #hdr ::selection,
#ftr::selection, #ftr ::selection, .fntext::selection, .fntext ::selection {
  background:rgba(59,130,246,.3); color:inherit;
}
/* Keep float wrapping without putting each text line in a separate flow-root. */
.docbody::after, .block::after { content:""; display:block; clear:both; }
